#include "engine/ai_controller.hpp"
#include "engine/editor_play.hpp"
#include <iostream>
#include <limits>
using namespace engine;
namespace {
int failures=0;
void check(bool ok,const char* label){if(!ok){++failures;std::cerr<<"FAIL: "<<label<<'\n';}}
template<class F>bool rejects(F f){try{f();return false;}catch(...){return true;}}
StateMachineData data(){StateMachineData d;d.states={{0,"Work","idle",{}},{1,"Done","idle",{}},{2,"Failure","idle",{}}};d.events={{"Done",{}},{"Failed",{}},{"AnimationFinished",{}},{"Damaged",{}}};d.states[0].succeededEvent="Done";d.states[0].failedEvent="Failed";d.transitions={{0,0,1,"always",0,"Done"},{1,0,2,"always",0,"Failed"},{2,0,2,"always",0,"Damaged"}};return d;}
AiControllerComponent& attach(Scene& scene,StateMachineData d){auto& a=scene.spawn("Agent");return a.addComponent<AiControllerComponent>("AI",AiControllerSettings::defaults(StateMachineDefinition::create(d),*AiBindingRegistry::builtins()));}
void sequence(){Scene scene;auto d=data();auto r=AiBindingRegistry::builtins();auto wait=r->taskDefaults("wait");wait.parameters["seconds"]=.2;auto event=r->taskDefaults("wait-event");event.event="AnimationFinished";d.states[0].tasks={wait,event};auto& ai=attach(scene,d);scene.fixedUpdate(.1);check(ai.activeTasks().front().status==AiTaskStatus::Running,"Task starts once and reports running");scene.fixedUpdate(.1);check(ai.taskHistory().size()==2&&ai.currentState()==0,"Successful first task defers next start to next tick");scene.fixedUpdate(.1);auto before=AiControllerArchive::save(ai.settings());auto token=ai.eventScope(0);ai.postEvent({"AnimationFinished",{}},token);scene.fixedUpdate(.1);check(ai.currentState()==0,"Event observation does not bypass task tick or transition cutoff");scene.fixedUpdate(.1);check(ai.currentState()==0&&ai.pendingEvents()==1,"Completion event waits for next tick");scene.fixedUpdate(.1);check(ai.currentState()==1&&ai.taskHistory().size()==4,"Sequence completes exactly once and transitions via scoped result");check(!ai.postEvent({"AnimationFinished",{}},token),"Late completion rejects after sequence exit");check(AiControllerArchive::save(ai.settings())==before,"Task clocks and outcomes excluded from configuration");ai.restart();scene.fixedUpdate(.1);check(ai.currentState()==0&&ai.taskHistory().size()==1,"Restart resets tasks and starts independent execution");ai.enabled=false;scene.fixedUpdate(.1);check(ai.taskHistory().back().status==AiTaskStatus::Canceled,"Disable cancels running work");}
void failure(){auto d=data();auto wait=AiBindingRegistry::builtins()->taskDefaults("wait");wait.timeout=.2;wait.parameters["seconds"]=1.0;d.states[0].tasks={wait};Scene scene;auto& ai=attach(scene,d);scene.fixedUpdate(.1);scene.fixedUpdate(.1);check(ai.taskHistory().back().error=="Task timed out","Timeout records failure reason");scene.fixedUpdate(.1);check(ai.currentState()==2,"Timeout uses declared failure event");ai.restart();scene.fixedUpdate(.1);ai.postEvent({"Damaged",{}});scene.fixedUpdate(.1);check(ai.currentState()==2&&ai.pendingEvents()==0,"Interrupt cancels scoped pending task result");
    Scene missing;d.states[0].tasks={AiBindingRegistry::builtins()->taskDefaults("move-to")};auto& a=missing.spawn("Missing nav");CharacterMotorSettings motor;motor.collisionAware=false;a.addComponent<CharacterMotorComponent>("Motor",motor);auto& bad=a.addComponent<AiControllerComponent>("AI",AiControllerSettings::defaults(StateMachineDefinition::create(d),*AiBindingRegistry::builtins()));missing.fixedUpdate(.1);check(bad.taskHistory().back().error.find("NavigationSource")!=std::string::npos,"Missing navigation becomes descriptive task failure");missing.fixedUpdate(.1);check(bad.currentState()==2,"Task start exceptions take failure edge");}
struct Probe:AiTask {int* starts;int* cancels;bool stop;Probe(int& s,int& c,bool p):starts(&s),cancels(&c),stop(p){}void start(AiControllerComponent&,const AiTaskSpec&,AiEventScope)override{++*starts;}AiTaskStatus tick(AiControllerComponent& c,double)override{if(stop)c.stop();return AiTaskStatus::Running;}void cancel(AiControllerComponent&)noexcept override{++*cancels;}};
struct StopOnStart:AiTask {int& ticks;int& cancels;StopOnStart(int& t,int& c):ticks(t),cancels(c){}void start(AiControllerComponent& c,const AiTaskSpec&,AiEventScope scope)override{check(scope.state==0&&scope.activation!=0,"Start receives the owning activation token");c.stop();}AiTaskStatus tick(AiControllerComponent&,double)override{++ticks;return AiTaskStatus::Running;}void cancel(AiControllerComponent&)noexcept override{++cancels;}};
// An application animation adapter owns the clip request. Its completion is
// marshaled to the controller's scene owner with the captured state scope.
struct AnimationAdapter:AiTask {int& requests;explicit AnimationAdapter(int& n):requests(n){}AiTaskStatus tick(AiControllerComponent&,double)override{++requests;return AiTaskStatus::Succeeded;}};
void movementExample(){
    auto r=AiBindingRegistry::builtins();int animations=0;auto tasks=r->tasks();tasks.push_back({"play-animation",{},false,[&]{return std::make_unique<AnimationAdapter>(animations);}});auto custom=AiBindingRegistry::create(r->behaviors(),r->conditions(),tasks);
    auto d=data();auto move=r->taskDefaults("move-to");move.parameters["target"]=Vec3{.6f,0,0};move.parameters["speed"]=2.0;move.parameters["distance"]=.1;
    auto face=r->taskDefaults("face-target");face.parameters["target"]=Vec3{5,0,0};auto wait=r->taskDefaults("wait-event");wait.event="AnimationFinished";
    d.states[0].tasks={move,face,custom->taskDefaults("play-animation"),wait};auto definition=StateMachineDefinition::create(d);Scene scene;auto& a=scene.spawn("Actor");CharacterMotorSettings ms;ms.collisionAware=false;auto& motor=a.addComponent<CharacterMotorComponent>("Motor",ms);auto& ai=a.addComponent<AiControllerComponent>("AI",AiControllerSettings::defaults(definition,*custom),custom);
    auto surface=std::make_shared<WaypointGraph>(std::vector<Vec3>{{0,0,0},{.6f,0,0}},std::vector<WaypointEdge>{{0,1},{1,0}});auto source=std::make_shared<NavigationSource>(surface);ai.setNavigationSource(source);ai.restart();scene.fixedUpdate(.1);auto revision=source->invalidate();scene.fixedUpdate(.1);check(motor.movementCommand().velocity.x==0&&ai.activeTasks().front().status==AiTaskStatus::Running,"Dirty navigation source waits without continuing stale motion");check(source->publish(revision,surface),"Navigation source republishes a matching revision");
    for(int i=0;i<15&&animations==0;++i)scene.fixedUpdate(.1);check(animations==1&&a.transform.position.x>.4f&&std::abs(a.transform.rotation.y-pi/2)<.001f,"MoveTo then FaceTarget then application animation adapter executes in order");scene.fixedUpdate(.1);check(ai.activeTasks().front().key=="wait-event","Sequence waits for application animation completion");auto scope=ai.eventScope(0);ai.postEvent({"AnimationFinished",{}},scope);for(int i=0;i<3;++i)scene.fixedUpdate(.1);check(ai.currentState()==1&&motor.movementCommand().velocity.x==0,"Animation completion finishes sequence and releases movement");
    ai.restart();scene.fixedUpdate(.1);ai.postEvent({"Damaged",{}});scene.fixedUpdate(.1);check(ai.currentState()==2&&motor.movementCommand().velocity.x==0,"Damage interruption cancels navigation immediately");
}
void queueAndHierarchy(){
    auto r=AiBindingRegistry::builtins();auto d=data();auto wait=r->taskDefaults("wait");wait.parameters["seconds"]=0.0;d.states[0].tasks={wait};Scene scene;auto& ai=attach(scene,d);for(int i=0;i<32;++i)ai.postEvent({"AnimationFinished",{}});scene.fixedUpdate(.1);check(ai.activeTasks().front().deliveryPending,"Full event queue retains terminal task result for retry");scene.fixedUpdate(.1);check(!ai.activeTasks().front().deliveryPending,"Result retries once queue space becomes available");for(int i=0;i<5;++i)scene.fixedUpdate(.1);check(ai.currentState()==1&&ai.taskHistory().size()==2,"Retry delivers once without rerunning completed task");
    auto h=data();h.states={{0,"Alive","idle",{}, {},1},{1,"Work","idle",{},0,{}},{2,"Other","idle",{},0,{}},{3,"Dead","idle",{}}};auto longWait=r->taskDefaults("wait");longWait.parameters["seconds"]=10.0;h.states[0].tasks={longWait};h.states[1].tasks={longWait};h.transitions={{0,1,2,"always",0,"AnimationFinished"},{1,0,3,"always",0,"Damaged"}};Scene hierarchy;auto& parent=attach(hierarchy,h);hierarchy.fixedUpdate(.1);parent.postEvent({"AnimationFinished",{}});hierarchy.fixedUpdate(.1);check(parent.activeTasks().size()==1&&parent.activeTasks()[0].state==0,"Sibling transition cancels child while preserving ancestor task");parent.postEvent({"Damaged",{}});hierarchy.fixedUpdate(.1);check(parent.activeTasks().empty()&&parent.taskHistory().back().status==AiTaskStatus::Canceled,"Parent interrupt cancels remaining task subtree");
}
void deadlineAndWorldFacing(){
    auto r=AiBindingRegistry::builtins();auto d=data();auto wait=r->taskDefaults("wait");wait.parameters["seconds"]=1.0;wait.timeout=1.0;d.states[0].tasks={wait};Scene scene;auto& ai=attach(scene,d);for(int i=0;i<10;++i)scene.fixedUpdate(.1);check(ai.taskHistory().back().status==AiTaskStatus::Succeeded,"Wait succeeds at an equal deadline despite floating point subtraction");
    Scene rotated;rotated.transform.rotation.y=.6f;auto& a=rotated.spawn("Facing");CharacterMotorSettings ms;ms.collisionAware=false;a.addComponent<CharacterMotorComponent>("Motor",ms);auto face=r->taskDefaults("face-target");face.parameters["target"]=Vec3{5,0,0};d.states[0].tasks={face};a.addComponent<AiControllerComponent>("AI",AiControllerSettings::defaults(StateMachineDefinition::create(d),*r));rotated.fixedUpdate(.1);auto forward=transformPoint(a.worldMatrix(),{0,0,1})-transformPoint(a.worldMatrix(),{});check(forward.x>.999f&&std::abs(forward.z)<.001f,"Facing uses world target under a rotated scene parent");
}
void lifetime(){int starts=0,cancels=0,ticks=0;auto builtin=AiBindingRegistry::builtins();auto tasks=builtin->tasks();tasks.push_back({"probe",{},false,[&]{return std::make_unique<Probe>(starts,cancels,true);}});tasks.push_back({"stop-start",{},false,[&]{return std::make_unique<StopOnStart>(ticks,cancels);}});auto r=AiBindingRegistry::create(builtin->behaviors(),builtin->conditions(),tasks);auto d=data();d.states[0].tasks={r->taskDefaults("probe")};Scene scene;auto& a=scene.spawn("Probe");auto& ai=a.addComponent<AiControllerComponent>("AI",AiControllerSettings::defaults(StateMachineDefinition::create(d),*r),r);scene.fixedUpdate(.1);check(starts==1&&cancels==1&&ai.status()==StateMachineStatus::Stopped,"Task callback stop defers ownership teardown safely and cancels once");d.states[0].tasks={r->taskDefaults("stop-start")};ai.configure(AiControllerSettings::defaults(StateMachineDefinition::create(d),*r));scene.fixedUpdate(.1);check(ticks==0&&cancels==2&&ai.status()==StateMachineStatus::Stopped,"Stop during start prevents subsequent tick and cleans up once");}
void persistence(){auto d=data();auto r=AiBindingRegistry::builtins();auto wait=r->taskDefaults("wait");d.blackboard={{"duration",AiParameterType::Number,.2,0,10}};wait.sources["seconds"]="duration";d.states[0].tasks={wait};auto def=StateMachineDefinition::create(d);auto text=StateMachineArchive::save(*def);check(text.starts_with("WEAI 5")&&StateMachineArchive::save(*StateMachineArchive::load(text))==text,"Task schemas sequences and result events roundtrip in WEAI5");check(StateMachineArchive::load("WEAI 4\n\"Old\" 0 1 0\n0 \"Idle\" \"idle\" 0 0 0 0 0 0\n0\n0\n")->data().states[0].tasks.empty(),"WEAI4 loads with empty task sequences");Scene scene;auto& ai=attach(scene,d);auto codecs=aiControllerCodecs();auto bytes=SceneArchive::save(scene,{}, {},{}, {},codecs);scene.fixedUpdate(.1);ai.setBlackboard({{"duration",5.0}});scene.fixedUpdate(.1);check(ai.taskHistory().back().status==AiTaskStatus::Succeeded,"Task snapshots blackboard inputs at start");EditorPlaySession play;play.start(scene,{}, {},codecs);auto* copy=dynamic_cast<AiControllerComponent*>(play.scene()->findSavedNode(ai.savedId()));check(copy&&copy->activeTasks().empty()&&copy->taskHistory().empty(),"Play clone excludes task instances/history");play.stop();check(SceneArchive::save(scene,{}, {},{}, {},codecs)==bytes,"Task execution and Play preserve source bytes");
    auto old=AiControllerArchive::save(ai.settings());auto invalid=d;invalid.states[0].tasks[0].parameters["seconds"]=true;check(rejects([&]{ai.configure(AiControllerSettings::defaults(StateMachineDefinition::create(invalid),*r));})&&AiControllerArchive::save(ai.settings())==old,"Invalid task binding preserves valid live configuration");invalid=d;invalid.states[0].tasks.resize(17,wait);check(rejects([&]{StateMachineDefinition::create(invalid);}),"Task sequence limit validates before publication");invalid=d;invalid.states[0].tasks[0].timeout=std::numeric_limits<double>::infinity();check(rejects([&]{StateMachineDefinition::create(invalid);}),"Nonfinite timeout rejects");invalid=d;invalid.states[0].succeededEvent="absent";check(rejects([&]{StateMachineDefinition::create(invalid);}),"Undeclared task result rejects");invalid=d;invalid.events[0].parameters={{"value",AiParameterType::Boolean,false}};check(rejects([&]{StateMachineDefinition::create(invalid);}),"Task results require empty payload schemas");}
}
int main(){try{sequence();failure();lifetime();persistence();movementExample();queueAndHierarchy();deadlineAndWorldFacing();}catch(const std::exception& e){std::cerr<<e.what()<<'\n';++failures;}return failures?1:0;}
